"use client";
import { useEffect, useState } from "react";
import Link from "next/link";
type Item = { id: string; name?: string; sku: string; category: string; supplier: string; stockQuantity: number | null; active: boolean; status: string; updatedAt: string | null };
export default function StockPage() { const [items, setItems] = useState<Item[]>([]); const [error, setError] = useState(""); useEffect(() => { queueMicrotask(() => { void (async () => { try { const response = await fetch("/api/admin/stock"); const data = await response.json() as { items?: Item[] }; if (!response.ok) throw new Error(); setItems(data.items ?? []); } catch { setError("No se pudo cargar el stock"); } })(); }); }, []); return <main className="ui-admin-main"><div className="mx-auto max-w-7xl"><div className="ui-surface ui-admin-header"><h1 className="text-3xl font-semibold">Stock</h1><Link href="/admin" className="ui-button-secondary">Volver</Link></div>{error ? <p className="text-rose-700">{error}</p> : null}<div className="ui-surface overflow-x-auto"><table className="ui-admin-table"><thead><tr><th>Producto</th><th>SKU</th><th>Categoría</th><th>Proveedor</th><th>Stock</th><th>Estado</th><th>Actualizado</th></tr></thead><tbody>{items.map((item) => <tr key={item.id}><td>{item.name ?? "Sin información"}</td><td>{item.sku}</td><td>{item.category}</td><td>{item.supplier}</td><td>{item.stockQuantity ?? "Desconocido"}</td><td>{item.status}</td><td>{item.updatedAt ? new Date(item.updatedAt).toLocaleString("es-AR") : "Sin información"}</td></tr>)}</tbody></table></div></div></main>; }
